import uuid
from datetime import datetime
from typing import Any

from sqlalchemy import CheckConstraint, DateTime, ForeignKey, Index, Integer, String, func, text
from sqlalchemy.dialects.postgresql import JSONB, UUID
from sqlalchemy.orm import Mapped, mapped_column

from app.models.base import Base
from app.models.enums import GOAL_MAX_LENGTH, MODES, STATUSES, TAGS, in_list


class FocusSession(Base):
    """A saved session (AC6.3). The id is generated by the client (AC13.4)."""

    __tablename__ = "focus_sessions"
    __table_args__ = (
        CheckConstraint(in_list("tag", TAGS), name="tag"),
        CheckConstraint(in_list("mode", MODES), name="mode"),
        CheckConstraint(in_list("status", STATUSES), name="status"),
        CheckConstraint(f"char_length(goal) <= {GOAL_MAX_LENGTH}", name="goal_length"),
        CheckConstraint("focus_seconds >= 0", name="focus_seconds"),
        CheckConstraint("paused_seconds >= 0", name="paused_seconds"),
        CheckConstraint("blocks_completed >= 0", name="blocks_completed"),
        CheckConstraint("ended_at >= started_at", name="ended_after_started"),
        # History: a user's sessions by start time, newest first (F10).
        Index("ix_focus_sessions_user_started", "user_id", text("started_at DESC")),
        # History filtered by tag (AC10.2).
        Index("ix_focus_sessions_user_tag_started", "user_id", "tag", text("started_at DESC")),
        # Archive view (AC11.3); only archived rows are indexed.
        Index(
            "ix_focus_sessions_user_archived",
            "user_id",
            "archived_at",
            postgresql_where=text("archived_at IS NOT NULL"),
        ),
    )

    id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True), primary_key=True)
    user_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True), ForeignKey("users.id", ondelete="CASCADE")
    )
    mode: Mapped[str] = mapped_column(String(16))
    tag: Mapped[str] = mapped_column(String(16))
    goal: Mapped[str | None] = mapped_column(String(GOAL_MAX_LENGTH), nullable=True)
    started_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))
    ended_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))
    focus_seconds: Mapped[int] = mapped_column(Integer)
    paused_seconds: Mapped[int] = mapped_column(Integer, server_default=text("0"))
    status: Mapped[str] = mapped_column(String(16))
    # The mode settings used (duration, Pomodoro config, reminder interval).
    mode_config: Mapped[dict[str, Any]] = mapped_column(JSONB, server_default=text("'{}'::jsonb"))
    # Completed focus blocks; meaningful for Pomodoro (AC3.6), 0 otherwise.
    blocks_completed: Mapped[int] = mapped_column(Integer, server_default=text("0"))
    archived_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), nullable=True)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now())
